function renderClients(){
 const q=window.clientQuery||'',uf=window.clientUF||'',city=window.clientCity||'',district=window.clientDistrict||'',sort=window.clientSort||'name';
 const cities=uniqueLocations(s.clients.filter(c=>!uf||stateCode(c)===uf).map(c=>c.city));
 const districts=uniqueLocations(s.clients.filter(c=>(!uf||stateCode(c)===uf)&&(!city||norm(c.city)===norm(city))).map(c=>c.district));
 const matches=s.clients.filter(c=>(!uf||stateCode(c)===uf)&&(!city||norm(c.city)===norm(city))&&(!district||norm(c.district)===norm(district))&&norm([c.name,c.tradeName,c.city,c.district,c.origin,c.channel,c.phone,c.brands].join(' ')).includes(norm(q)));
 const byName=(a,b)=>String(a.name||'').localeCompare(String(b.name||''),'pt-BR');
 matches.sort((a,b)=>sort==='city'?norm(a.city).localeCompare(norm(b.city))||norm(a.district).localeCompare(norm(b.district))||byName(a,b):sort==='district'?norm(a.city).localeCompare(norm(b.city))||norm(a.district).localeCompare(norm(b.district))||byName(a,b):sort==='origin'?norm(a.origin||a.channel).localeCompare(norm(b.origin||b.channel))||byName(a,b):byName(a,b));
 const pageSize=50,pages=Math.max(1,Math.ceil(matches.length/pageSize)),page=Math.min(Math.max(0,Number(window.clientPage)||0),pages-1);
 const items=matches.slice(page*pageSize,(page+1)*pageSize);
 let previous='',rows=items.map(c=>{
  const group=sort==='city'?((c.city||'Cidade não informada')+' / '+(stateCode(c)||'UF pendente')):sort==='district'?((c.city||'Cidade não informada')+' · '+(c.district||'Bairro não informado')):sort==='origin'?(c.origin||c.channel||'Origem não informada'):((c.name||'#').normalize('NFD').replace(/[\u0300-\u036f]/g,'').charAt(0).toUpperCase()||'#');
  const heading=group!==previous?'<div class="client-group">'+esc(group)+'</div>':'';previous=group;
  return heading+'<div class="client-row"><button class="client-edit" title="Editar cadastro de '+esc(c.name)+'" aria-label="Editar cadastro de '+esc(c.name)+'" onclick="editClient(\''+esc(c.id)+'\')">✎</button><div class="client-main"><button class="client-name" onclick="openClient360(\''+esc(c.id)+'\')">'+esc(c.name)+'</button><small>'+esc(c.tradeName?c.tradeName+' · ':'')+esc(c.origin||c.channel||'Origem não informada')+'</small></div><div class="client-place">'+esc(c.city||'Cidade pendente')+' · '+esc(c.district||'Bairro pendente')+' <span class="uf-badge">'+esc(stateCode(c)||'—')+'</span></div><div class="client-actions"><button type="button" onclick="openClient360(\''+esc(c.id)+'\')">Histórico</button><button type="button" class="secondary" onclick="prefill(\''+esc(c.id)+'\')">Atender</button>'+(s.user==='Ana Paula'?'<button type="button" class="secondary" onclick="deleteEntity(\'client\',\''+esc(c.id)+'\')">Excluir</button>':'')+'</div></div>'
 }).join('');
 return `<div class="page-heading"><div><span class="eyebrow">Carteira comercial</span><h2>Clientes</h2><p>Encontre o cadastro e abra seu histórico de visitas, pedidos e negociações.</p></div><button type="button" onclick="newClient()">+ Novo cliente</button></div>
 <div class="box client-filters"><label>Buscar cliente, nome fantasia, cidade ou bairro<input id="q" type="search" placeholder="Digite nome, cidade, bairro ou origem" value="${esc(q)}" oninput="let caret=this.selectionStart;window.clientQuery=this.value;window.clientPage=0;show('clientes');$('q').focus();$('q').setSelectionRange(caret,caret)"></label>
 <div class="row"><label>Organizar<select onchange="window.clientSort=this.value;window.clientPage=0;show('clientes')"><option value="name" ${sort==='name'?'selected':''}>Ordem alfabética</option><option value="city" ${sort==='city'?'selected':''}>Cidade e bairro</option><option value="district" ${sort==='district'?'selected':''}>Bairros por cidade</option><option value="origin" ${sort==='origin'?'selected':''}>Origem</option></select></label>
 <label>Estado<select onchange="window.clientUF=this.value;window.clientCity='';window.clientDistrict='';window.clientPage=0;show('clientes')"><option value="">PA e AP</option>${['PA','AP'].map(v=>`<option value="${v}" ${uf===v?'selected':''}>${v}</option>`).join('')}</select></label>
 <label>Cidade<select onchange="window.clientCity=this.value;window.clientDistrict='';window.clientPage=0;show('clientes')"><option value="">Todas as cidades</option>${cities.map(v=>`<option value="${esc(v)}" ${norm(city)===norm(v)?'selected':''}>${esc(v)}</option>`).join('')}</select></label>
 <label>Bairro<select onchange="window.clientDistrict=this.value;window.clientPage=0;show('clientes')"><option value="">Todos os bairros</option>${districts.map(v=>`<option value="${esc(v)}" ${norm(district)===norm(v)?'selected':''}>${esc(v)}</option>`).join('')}</select></label></div>
 <p class="muted">${matches.length} de ${s.clients.length} clientes · página ${page+1} de ${pages}. A lista não repete o cliente por pedido.</p></div>
 <section class="box client-directory" aria-label="Lista de clientes"><div class="client-list-head"><span>Cliente</span><span>Cidade · bairro</span><span>Ações</span></div>${rows||'<p>Nenhum cliente encontrado. Ajuste a busca ou os filtros.</p>'}
 <div class="client-pager"><button type="button" class="secondary" ${page===0?'disabled':''} onclick="window.clientPage=${page-1};show('clientes')">Anterior</button><span>${page+1} / ${pages}</span><button type="button" class="secondary" ${page>=pages-1?'disabled':''} onclick="window.clientPage=${page+1};show('clientes')">Próxima</button></div></section>
 <details id="clientEditor" class="box"><summary>Cadastro de cliente</summary><div class="box"><h3 id="clientFormTitle">Cadastrar novo cliente</h3><p class="muted">Informe a UF do cadastro para aplicar a tabela de preços correta nos pedidos.</p><form id="clientForm"><input type="hidden" name="id" id="cid"><div class="row"><label>Razão social / Nome<input name="name" id="c_name" required maxlength="180"></label><label>Nome fantasia<input name="tradeName" id="c_tradeName" maxlength="180"></label><label>CNPJ<input name="taxId" id="c_taxId" inputmode="numeric" maxlength="18" placeholder="00.000.000/0000-00" required></label><label>Inscrição estadual<input name="stateRegistration" id="c_stateRegistration" inputmode="numeric" maxlength="20" placeholder="Informe a IE ou ISENTO" required></label><label>Contato<input name="contact" id="c_contact"></label><label>WhatsApp<input name="phone" id="c_phone" type="tel"></label><label>E-mail<input name="email" id="c_email" type="email"></label><label>Endereço<input name="address" id="c_address"></label><label>Bairro<input name="district" id="c_district"></label><label>Cidade<input name="city" id="c_city" required></label><label>UF<select name="state" id="c_state" required><option value="">Selecione</option><option value="PA">Pará (PA)</option><option value="AP">Amapá (AP)</option></select></label><label>Canal<input name="channel" id="c_channel" placeholder="Ex.: Farma"></label><label>Origem do cliente<input name="origin" id="c_origin" placeholder="Ex.: Indicação, prospecção"></label><label>Responsável<select name="owner" id="c_owner"><option value="">Selecione</option>${teamOptions()}</select></label><label>Classificação<select name="classification" id="c_classification"><option value="">Selecione</option><option>A</option><option>B</option><option>C</option><option>D</option></select></label><label>Potencial estimado (R$)<input name="potential" id="c_potential" inputmode="decimal" placeholder="0,00"></label><label>Dia preferido de visita<input name="visitDay" id="c_visitDay" placeholder="Ex.: terça-feira"></label><label>Marcas<input name="brands" id="c_brands"></label><label>Última compra<input name="last_purchase" id="c_last_purchase" type="date"></label></div><button type="submit">Salvar cliente</button> <button type="button" class="secondary" onclick="newClient()">Limpar / novo cadastro</button></form></div></details>`
}


function renderClientRepository(c){
 const id=esc(c.id);
 return `<section class="box" aria-label="Histórico Documental e Registros"><h3>📂 Repositório documental: ${esc(c.name)}</h3>
 <p>CNPJ/CPF: ${esc(c.taxId||'Não informado')} · Curva ABC: ${esc(c.abc||'Não cadastrada')}<br>Status do histórico: Ativo (controle a partir de 28/09/2026)</p>
 <p class="muted">Arquivos anteriores não sincronizados podem ser inseridos manualmente. Nenhum documento retroativo é criado automaticamente.</p>
 <p id="clientDocsStatus">Carregando documentos…</p><div class="cards">
 <div class="card"><h4>📄 Notas Fiscais (NFE)</h4><div id="clientDocsNfe"></div><label>+ Adicionar NFE<input type="file" accept=".xml,.pdf" onchange="uploadClientDocument('${id}','nfe',this)"></label></div>
 ${financeAllowed()?`<div class="card"><h4>💳 Financeiro (boletos e comprovantes)</h4><div id="clientDocsFinance"></div><label>+ Adicionar Boleto ou Comprovante<input type="file" accept=".pdf,.jpg,.jpeg,.png" onchange="uploadClientDocument('${id}','finance',this)"></label></div>`:''}
 <div class="card"><h4>📝 Contratos e cadastros</h4><div id="clientDocsContract"></div><label>+ Novo Arquivo<input type="file" accept=".pdf,.jpg,.jpeg,.png" onchange="uploadClientDocument('${id}','contract',this)"></label></div>
 <div class="card"><h4>💬 Notas de atendimento e histórico</h4><div id="clientDocsNote"></div><form onsubmit="saveClientNote(event,'${id}')"><label>Registrar interação<textarea name="text" rows="3" maxlength="4000" required></textarea></label><button>Salvar registro</button></form></div></div></section>`;
}
async function loadClientRepository(id){
 const status=$('clientDocsStatus');if(!status)return;
 if(!s.token){status.textContent='Entre no sistema para acessar documentos protegidos.';return}
 try{
  const response=await fetch(s.server+'/api/clients/'+encodeURIComponent(id)+'/documents',{headers:{Authorization:'Bearer '+s.token}});
  const rows=await response.json();if(!response.ok)throw Error(rows.detail||'Consulta recusada');
  status.textContent=rows.length?rows.length+' registro(s) neste cliente.':'Nenhum documento ou registro anexado a este cliente.';
  for(const [category,target] of [['nfe','clientDocsNfe'],['finance','clientDocsFinance'],['contract','clientDocsContract'],['note','clientDocsNote']]){
   const area=$(target);if(!area)continue;const files=rows.filter(x=>x.category===category);
   const fallback=category==='nfe'||category==='finance'?'Documento indisponível - Vigência de histórico iniciada em 28/09/2026':'Nenhum registro nesta seção.';
   area.innerHTML=files.length?files.map(x=>`<p><b>${esc(x.name||new Date(x.createdAt).toLocaleDateString('pt-BR'))}</b> ${x.note?esc(x.note):''}<br><small>${esc(x.uploadedBy)} · ${esc(new Date(x.createdAt).toLocaleString('pt-BR'))}</small><br>${x.category==='note'?'':`<button type="button" onclick="downloadClientDocument('${esc(id)}','${esc(x.id)}','${esc(encodeURIComponent(x.name))}')">Baixar</button>`} <button type="button" class="secondary" onclick="deleteClientDocument('${esc(id)}','${esc(x.id)}')">Excluir</button></p>`).join(''):'<p class="muted">'+fallback+'</p>';
  }
 }catch(err){status.textContent=err.message}
}
async function uploadClientDocument(id,category,input){
 const file=input.files?.[0];if(!file)return;if(file.size===0||file.size>10*1024*1024){alert('Arquivo deve ter até 10 MB.');input.value='';return}
 const body=new FormData();body.append('file',file);
 try{const response=await fetch(s.server+'/api/clients/'+encodeURIComponent(id)+'/documents?category='+encodeURIComponent(category),{method:'POST',headers:{Authorization:'Bearer '+s.token},body});const data=await response.json();if(!response.ok)throw Error(data.detail||'Upload recusado');input.value='';await loadClientRepository(id)}catch(err){alert(err.message)}
}
async function saveClientNote(event,id){
 event.preventDefault();const text=event.target.elements.text.value.trim();if(!text)return;
 try{const response=await fetch(s.server+'/api/clients/'+encodeURIComponent(id)+'/notes',{method:'POST',headers:{Authorization:'Bearer '+s.token,'Content-Type':'application/json'},body:JSON.stringify({text})});const data=await response.json();if(!response.ok)throw Error(data.detail||'Registro recusado');event.target.reset();await loadClientRepository(id)}catch(err){alert(err.message)}
}
async function downloadClientDocument(id,docId,name){
 try{const response=await fetch(s.server+'/api/clients/'+encodeURIComponent(id)+'/documents/'+encodeURIComponent(docId),{headers:{Authorization:'Bearer '+s.token}});if(!response.ok)throw Error('Download recusado');downloadBlob(await response.blob(),decodeURIComponent(name))}catch(err){alert(err.message)}
}
async function deleteClientDocument(id,docId){
 if(!confirm('Excluir este documento ou anotação?'))return;
 try{const response=await fetch(s.server+'/api/clients/'+encodeURIComponent(id)+'/documents/'+encodeURIComponent(docId),{method:'DELETE',headers:{Authorization:'Bearer '+s.token}});if(!response.ok){const data=await response.json().catch(()=>({}));throw Error(data.detail||'Exclusão recusada')}await loadClientRepository(id)}catch(err){alert(err.message)}
}

const CRM_STAGES=['Prospectado','Qualificado','Visita agendada','Proposta enviada','Negociação','Ganho','Pedido confirmado','Faturado','Entregue','Pós-venda','Perdido'];
const CRM_OWNERS=['Ana Paula','Euler','Laís','Marlene'];
function openClient360(id){window.crmClientId=id;show('crm')}
function crmDateTime(value){return value?String(value).replace('T',' ').slice(0,16):'—'}
function renderCRM(){
 const selected=s.clients.find(c=>c.id===window.crmClientId);
 const all=s.opportunities||[], active=all.filter(x=>x.stage!=='Perdido'&&x.stage!=='Pós-venda');
 const overdue=active.filter(x=>x.followUp&&x.followUp<today()).length;
 const related=selected?all.filter(x=>x.clientId===selected.id):all;
 const events=selected?[
  ...(s.interactions||[]).filter(x=>x.clientId===selected.id).map(x=>({at:x.at,label:x.type,text:x.text,by:x.owner})),
  ...s.visits.filter(x=>x.clientId===selected.id).map(x=>({at:x.date,label:'Visita',text:x.result||x.notes||'',by:x.user})),
  ...s.orders.filter(x=>x.clientId===selected.id).map(x=>({at:x.date,label:'Pedido '+orderLabel(x.orderNumber),text:(x.brand||'')+' · '+money(x.amount)+' · '+(x.status||''),by:x.user})),
  ...s.tasks.filter(x=>x.clientId===selected.id).map(x=>({at:x.date,label:'Tarefa',text:(x.text||'')+' · '+(x.status||''),by:x.user})),
  ...s.fulfillments.filter(x=>x.clientId===selected.id).map(x=>({at:x.at,label:'Operação',text:x.stage+' · '+(x.notes||''),by:x.owner}))
 ].sort((a,b)=>String(b.at||'').localeCompare(String(a.at||''))):[];
 const clientOptions=s.clients.slice().sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')).map(c=>`<option value="${esc(c.id)}" ${selected?.id===c.id?'selected':''}>${esc(c.name)} · ${esc(c.city||'')} / ${esc(stateCode(c))}</option>`).join('');
 const stageCards=CRM_STAGES.filter(x=>x!=='Perdido').map(stage=>{const rows=all.filter(x=>x.stage===stage);return `<div class="card">${esc(stage)}<strong>${rows.length}</strong><small>${money(rows.reduce((n,x)=>n+Number(x.amount||0),0))}</small></div>`}).join('');
 return `<div class="page-heading"><div><span class="eyebrow">Carteira e negociações</span><h2>Visão 360º e funil</h2><p>Histórico compartilhado, próximas ações e etapas por cliente e indústria.</p></div></div>
 <div class="cards">${stageCards}</div><p class="muted">${overdue} oportunidade(s) com retorno vencido. Valores representam previsão comercial; faturamento e comissão recebida são controlados separadamente.</p>
 <div class="box"><label>Cliente da visão 360º<select onchange="window.crmClientId=this.value;show('crm')"><option value="">Todas as oportunidades</option>${clientOptions}</select></label>
 ${selected?`<h3>${esc(selected.name)}</h3><p>${esc(selected.tradeName||'')} · ${esc(selected.taxId||'CNPJ não informado')} · ${esc(selected.city||'')} / ${esc(stateCode(selected))} · ${esc(selected.district||'')}</p><p>Contato: ${esc(selected.contact||'—')} · ${esc(selected.phone||'—')} · ${esc(selected.email||'—')}<br>Responsável: ${esc(selected.owner||'Não definido')} · Canal: ${esc(selected.channel||'—')} · Marcas: ${esc(selected.brands||'—')}</p><p>Origem: ${esc(selected.origin||'Não informada')} · Última compra: ${esc(selected.last_purchase||'Não informada')} · Visitas: ${s.visits.filter(x=>x.clientId===selected.id).length} · Pedidos: ${s.orders.filter(x=>x.clientId===selected.id).length} · Ações abertas: ${s.tasks.filter(x=>x.clientId===selected.id&&x.status!=='Concluída').length}</p><button type="button" onclick="editClient('${esc(selected.id)}')">Editar cadastro</button> <button type="button" onclick="prefill('${esc(selected.id)}')">Registrar visita</button> <button type="button" onclick="window.prefillId='${esc(selected.id)}';show('pedidos')">Novo pedido</button>`:'<p>Selecione um cliente para consultar sua linha do tempo e registrar interações.</p>'}</div>
 ${selected?renderClientRepository(selected):''}
 <div class="box"><h3>Oportunidades</h3><div class="scroll"><table><tr><th>Cliente / indústria</th><th>Etapa</th><th>Responsável</th><th>Previsão</th><th>Próxima ação</th><th>Valor</th><th>Ações</th></tr>${related.slice().sort((a,b)=>String(a.followUp||'9999').localeCompare(String(b.followUp||'9999'))).map(x=>`<tr><td>${esc(client(x.clientId).name||'—')}<br>${esc(x.brand)}</td><td>${esc(x.stage)}</td><td>${esc(x.owner)}</td><td>${esc(x.closeDate||'—')}</td><td>${esc(x.followUp||'—')}${x.followUp&&x.followUp<today()&&x.stage!=='Perdido'&&x.stage!=='Pós-venda'?' · Vencida':''}</td><td>${money(x.amount)}</td><td><button onclick="editCRMOpportunity('${esc(x.id)}')">Editar</button> <button class="secondary" onclick="deleteEntity('opportunity','${esc(x.id)}')">Excluir</button></td></tr>`).join('')||'<tr><td colspan="7">Nenhuma oportunidade cadastrada.</td></tr>'}</table></div>
 <form id="crmOpportunityForm" onsubmit="saveCRMOpportunity(event)"><h3 id="crmOpportunityTitle">Nova oportunidade</h3><input name="id" type="hidden"><div class="row"><label>Cliente<select name="clientId" required><option value="">Selecione</option>${clientOptions}</select></label><label>Indústria / marca<input name="brand" required maxlength="120"></label><label>Etapa<select name="stage">${CRM_STAGES.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Responsável<select name="owner">${teamNames().map(x=>`<option ${x===s.user?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Valor previsto (R$)<input name="amount" inputmode="decimal" placeholder="0,00" required></label><label>Previsão de fechamento<input name="closeDate" type="date"></label><label>Próximo contato<input name="followUp" type="date"></label><label>Motivo de perda<input name="lossReason" maxlength="180"></label></div><label>Contexto da negociação<textarea name="notes" rows="3" maxlength="2000"></textarea></label><button>Salvar oportunidade</button> <button type="button" class="secondary" onclick="this.form.reset();this.form.elements.id.value='';$('crmOpportunityTitle').textContent='Nova oportunidade'">Nova</button></form></div>
 ${selected?`<div class="box"><h3>Registrar interação</h3><form onsubmit="saveCRMInteraction(event)"><input type="hidden" name="clientId" value="${esc(selected.id)}"><div class="row"><label>Tipo<select name="type"><option>Conversa</option><option>Ligação</option><option>WhatsApp</option><option>E-mail</option><option>Reunião</option><option>Ocorrência</option><option>Pós-venda</option></select></label><label>Responsável<select name="owner">${teamNames().map(x=>`<option ${x===s.user?'selected':''}>${esc(x)}</option>`).join('')}</select></label></div><label>Resumo da interação<textarea name="text" required rows="3" maxlength="2000" placeholder="Registre o resumo e o próximo passo; mensagens não são importadas automaticamente."></textarea></label><button>Registrar no histórico</button></form></div><div class="box"><h3>Linha do tempo do cliente</h3>${events.slice(0,100).map(x=>`<p><strong>${esc(crmDateTime(x.at))} · ${esc(x.label)}</strong> · ${esc(x.by||'')}<br>${esc(x.text||'—')}</p>`).join('')||'<p>Nenhum evento registrado.</p>'}</div>`:''}`;
}
function editCRMOpportunity(id){const x=s.opportunities.find(v=>v.id===id);if(!x)return;window.crmClientId=x.clientId;show('crm');const form=$('crmOpportunityForm');for(const name of ['id','clientId','brand','stage','owner','closeDate','followUp','lossReason','notes'])form.elements[name].value=x[name]||'';form.elements.amount.value=formatBRLInput(x.amount);$('crmOpportunityTitle').textContent='Editar oportunidade';form.scrollIntoView({behavior:'smooth',block:'start'})}
function saveCRMOpportunity(event){
 event.preventDefault();const form=event.target,d=Object.fromEntries(new FormData(form)),cents=parseBRLCents(d.amount);
 if(!s.clients.some(x=>x.id===d.clientId)||!Number.isSafeInteger(cents)||cents<0||cents>1e12)return alert('Selecione um cliente e informe um valor válido.');
 if(d.stage==='Perdido'&&!d.lossReason.trim())return alert('Informe o motivo da perda.');
 const old=s.opportunities.find(x=>x.id===d.id);d.id=d.id||uid();d.brand=d.brand.trim();d.amount=(cents/100).toFixed(2);d.notes=d.notes.trim();d.updatedAt=new Date().toISOString();d.createdAt=old?.createdAt||d.updatedAt;d.wonAt=['Ganho','Pedido confirmado'].includes(d.stage)?(old?.wonAt||d.updatedAt):'';
 s.opportunities=s.opportunities.filter(x=>x.id!==d.id);s.opportunities.push({...old,...d});window.crmClientId=d.clientId;queue('opportunity',{...old,...d});
 if(d.followUp&&d.stage!=='Perdido'&&d.stage!=='Pós-venda'&&(!old||old.followUp!==d.followUp||old.owner!==d.owner)){
  const previous=s.tasks.find(x=>x.sourceOpportunityId===d.id&&x.status!=='Concluída');
  const task={...previous,id:previous?.id||uid(),clientId:d.clientId,sourceOpportunityId:d.id,text:'Retornar negociação '+d.brand,date:d.followUp,user:d.owner,status:'Aberta'};
  s.tasks=s.tasks.filter(x=>x.id!==task.id);s.tasks.push(task);queue('task',task)
 }
 show('crm')
}
function saveCRMInteraction(event){event.preventDefault();const d=Object.fromEntries(new FormData(event.target));if(!s.clients.some(x=>x.id===d.clientId)||!d.text.trim())return alert('Selecione um cliente e descreva a interação.');d.id=uid();d.text=d.text.trim();d.at=new Date().toISOString();s.interactions.push(d);queue('interaction',d);show('crm')}


const ORDER_FLOW=['Conferência','Enviado à indústria','Confirmado pela indústria','Faturado','Em transporte','Entregue','Pós-venda concluído','Ocorrência'];
function renderOperations(){
 const rows=s.orders.filter(x=>x.status!=='Cancelado').slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
 const records=s.fulfillments||[];
 const due=records.filter(x=>x.due&&x.due<today()&&!['Entregue','Pós-venda concluído'].includes(x.stage));
 return `<div class="page-heading"><div><span class="eyebrow">Retaguarda comercial</span><h2>Acompanhamento dos pedidos</h2><p>Conferência, indústria, faturamento, transporte, entrega e pós-venda.</p></div></div>
 <div class="cards"><div class="card">Pedidos ativos<strong>${rows.length}</strong></div><div class="card">Em acompanhamento<strong>${records.length}</strong></div><div class="card">Prazo vencido<strong>${due.length}</strong></div><div class="card">Entregues<strong>${records.filter(x=>x.stage==='Entregue'||x.stage==='Pós-venda concluído').length}</strong></div></div>
 <div class="box"><h3>Fila operacional</h3><div class="scroll"><table><tr><th>Pedido</th><th>Cliente / indústria</th><th>Etapa</th><th>Responsável</th><th>Prazo</th><th>Ação</th></tr>
 ${rows.map(o=>{const x=records.find(v=>v.orderId===o.id);return `<tr><td>${esc(orderLabel(o.orderNumber))}</td><td>${esc(client(o.clientId).name||'—')}<br>${esc(o.brand||'—')}</td><td>${esc(x?.stage||'Sem acompanhamento')}</td><td>${esc(x?.owner||'—')}</td><td>${esc(x?.due||'—')}${x?.due&&x.due<today()&&x.stage!=='Entregue'&&x.stage!=='Pós-venda concluído'?' · Vencido':''}</td><td><button onclick="editFulfillment('${esc(o.id)}')">${x?'Atualizar':'Iniciar'}</button></td></tr>`}).join('')||'<tr><td colspan="6">Nenhum pedido ativo.</td></tr>'}</table></div>
 <form id="fulfillmentForm" onsubmit="saveFulfillment(event)"><h3>Ação operacional</h3><input name="id" type="hidden"><label>Pedido<select name="orderId" required onchange="editFulfillment(this.value)"><option value="">Selecione</option>${rows.map(o=>`<option value="${esc(o.id)}">${esc(orderLabel(o.orderNumber))} · ${esc(client(o.clientId).name||'—')} · ${esc(o.brand||'')}</option>`).join('')}</select></label><div class="row"><label>Etapa<select name="stage">${ORDER_FLOW.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Responsável<select name="owner">${teamNames().map(x=>`<option ${x==='Laís'?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Prazo da etapa<input name="due" type="date"></label></div><label>Atualização / ocorrência<textarea name="notes" rows="3" maxlength="2000"></textarea></label><button>Salvar acompanhamento</button></form></div>`;
}
function editFulfillment(orderId){const o=s.orders.find(x=>x.id===orderId);if(!o)return;const x=s.fulfillments.find(v=>v.orderId===orderId),form=$('fulfillmentForm');form.elements.id.value=x?.id||'';form.elements.orderId.value=orderId;form.elements.stage.value=x?.stage||'Conferência';form.elements.owner.value=x?.owner||'Laís';form.elements.due.value=x?.due||'';form.elements.notes.value=x?.notes||'';form.scrollIntoView({behavior:'smooth',block:'start'})}
function saveFulfillment(event){event.preventDefault();const d=Object.fromEntries(new FormData(event.target)),o=s.orders.find(x=>x.id===d.orderId);if(!o)return alert('Escolha um pedido ativo.');d.id=d.id||uid();d.clientId=o.clientId;d.at=new Date().toISOString();d.notes=d.notes.trim();s.fulfillments=s.fulfillments.filter(x=>x.id!==d.id);s.fulfillments.push(d);queue('fulfillment',d);show('operations')}
function beginOrderWorkflow(o){if(s.fulfillments.some(x=>x.orderId===o.id))return;const due=new Date(Date.now()+2*864e5).toLocaleDateString('sv-SE');const d={id:uid(),orderId:o.id,clientId:o.clientId,stage:'Conferência',owner:'Laís',due,notes:'Acompanhamento iniciado após confirmação do pedido.',at:new Date().toISOString()};s.fulfillments.push(d);queue('fulfillment',d)}


function renderSettlements(){
 if(!financeAllowed())return '<p>Acesso financeiro restrito.</p>';
 const records=s.settlements||[],billedCents=records.reduce((n,x)=>n+Math.round(Number(x.billed||0)*100),0);
 const dueCents=records.reduce((n,x)=>n+Math.round(Number(x.commissionDue||0)*100)-Math.round(Number(x.commissionReceived||0)*100),0);
 const receivedCents=records.reduce((n,x)=>n+Math.round(Number(x.commissionReceived||0)*100),0);
 const orders=s.orders.filter(o=>o.status!=='Cancelado').slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
 return `<div class="cards"><div class="card">Faturado informado<strong>${money(billedCents/100)}</strong></div><div class="card">Comissão a receber<strong>${money(dueCents/100)}</strong></div><div class="card">Comissão recebida<strong>${money(receivedCents/100)}</strong></div></div>
 <div class="box"><h3>Conciliação por pedido</h3><p class="muted">Registre somente dados confirmados pelo documento da indústria. Comissão não é considerada recebida até informar o pagamento. Valores negativos indicam divergência a conferir.</p><div class="scroll"><table><tr><th>Pedido / cliente</th><th>NF / faturamento</th><th>Comissão %</th><th>Devida</th><th>Recebida</th><th>Vencimento</th><th>Margem estimada</th><th>Ações</th></tr>
 ${records.slice().sort((a,b)=>String(b.billedDate||'').localeCompare(String(a.billedDate||''))).map(x=>{const o=s.orders.find(v=>v.id===x.orderId);return `<tr><td>${esc(orderLabel(o?.orderNumber))} · ${esc(client(x.clientId).name||'—')}</td><td>${esc(x.invoiceNumber||'—')} · ${money(x.billed)}</td><td>${esc(x.rate)}%</td><td>${money(x.commissionDue)}</td><td>${money(x.commissionReceived)}</td><td>${esc(x.due||'—')}</td><td>${money((Number(x.commissionDue||0)-Number(x.allocatedCost||0)))}</td><td><button onclick="editSettlement('${esc(x.id)}')">Editar</button> <button class="secondary" onclick="deleteEntity('settlement','${esc(x.id)}')">Excluir</button></td></tr>`}).join('')||'<tr><td colspan="8">Nenhum faturamento conciliado.</td></tr>'}</table></div>
 <form id="settlementForm" onsubmit="saveSettlement(event)"><h3 id="settlementTitle">Registrar faturamento</h3><input name="id" type="hidden"><div class="row"><label>Pedido<select name="orderId" required onchange="suggestSettlementRate(this.form)"><option value="">Selecione</option>${orders.map(o=>`<option value="${esc(o.id)}">${esc(orderLabel(o.orderNumber))} · ${esc(client(o.clientId).name||'—')} · ${esc(o.brand)}</option>`).join('')}</select></label><label>Nº documento da indústria<input name="invoiceNumber" required maxlength="80"></label><label>Data do faturamento<input name="billedDate" type="date" required></label><label>Valor faturado (R$)<input name="billed" inputmode="decimal" placeholder="0,00" required></label><label>Comissão (%)<input name="rate" inputmode="decimal" placeholder="5,00" required></label><label>Vencimento da comissão<input name="due" type="date"></label><label>Comissão recebida (R$)<input name="commissionReceived" inputmode="decimal" placeholder="0,00"></label><label>Data do recebimento<input name="receivedDate" type="date"></label><label>Custo atribuído (R$)<input name="allocatedCost" inputmode="decimal" placeholder="0,00"></label></div><label>Observação / divergência<textarea name="notes" rows="2" maxlength="1000"></textarea></label><button>Salvar conciliação</button> <button type="button" class="secondary" onclick="this.form.reset();this.form.elements.id.value='';$('settlementTitle').textContent='Registrar faturamento'">Novo lançamento</button></form></div>`;
}
function suggestSettlementRate(form){const o=s.orders.find(x=>x.id===form.elements.orderId.value);if(!o)return;const rate=s.commissionRates.find(x=>x.id===commissionKey(o.brand))?.rate;form.elements.rate.value=rate===undefined?'':String(rate).replace('.',',');form.elements.billed.value=formatBRLInput(o.amount)}
function editSettlement(id){const x=s.settlements.find(v=>v.id===id);if(!x)return;window.financeSection='conciliacao';show('finance');const f=$('settlementForm');for(const k of ['id','orderId','invoiceNumber','billedDate','rate','due','receivedDate','notes'])f.elements[k].value=x[k]||'';for(const k of ['billed','commissionReceived','allocatedCost'])f.elements[k].value=formatBRLInput(x[k]);$('settlementTitle').textContent='Editar conciliação';f.scrollIntoView({behavior:'smooth',block:'start'})}
function saveSettlement(event){
 event.preventDefault();if(!financeAllowed())return;const f=event.target,d=Object.fromEntries(new FormData(f)),o=s.orders.find(x=>x.id===d.orderId);if(!o)return alert('Selecione o pedido.');
 const moneyFields=['billed','commissionReceived','allocatedCost'],cents={};
 for(const field of moneyFields){const value=parseBRLCents(d[field]||'0');if(!Number.isSafeInteger(value)||value<0||value>1e12)return alert('Confira o valor de '+field+'.');cents[field]=value;d[field]=(value/100).toFixed(2)}
 const rate=commissionPercent(d.rate);if(!Number.isFinite(rate)||rate<0||rate>100)return alert('Informe comissão percentual válida.');
 const dueCents=Math.round(cents.billed*rate/100);d.commissionDue=(dueCents/100).toFixed(2);
 if(cents.commissionReceived>dueCents)return alert('Comissão recebida superior à prevista. Registre a divergência antes de lançar.');
 if(cents.commissionReceived>0&&!d.receivedDate)return alert('Informe a data do recebimento.');
 if(s.settlements.some(x=>x.id!==d.id&&x.orderId===d.orderId&&x.invoiceNumber===d.invoiceNumber.trim()))return alert('Este documento já está vinculado ao pedido.');
 d.id=d.id||uid();d.invoiceNumber=d.invoiceNumber.trim();d.clientId=o.clientId;d.brand=o.brand;d.rate=rate;d.notes=d.notes.trim();d.updatedAt=new Date().toISOString();
 s.settlements=s.settlements.filter(x=>x.id!==d.id);s.settlements.push(d);queue('settlement',d);show('finance')
}


const ACCESS_SECTORS=[['commercial','Comercial'],['clients_edit','Editar clientes'],['routes','Rotas'],['office','Escritório'],['management','Gestão'],['finance','Financeiro e caixa'],['catalog','Catálogo']];
function sectorCheckboxes(selected=[],prefix=''){return ACCESS_SECTORS.map(([key,label])=>`<label style="display:inline-flex;align-items:center;margin:.5rem"><input type="checkbox" name="sectors" value="${key}" ${selected.includes(key)?'checked':''}> ${label}</label>`).join('')}
function renderAdmin(){
 if(s.user!=='Ana Paula'||!s.token)return '<p>Acesso restrito.</p>';
 const brands=(s.industries||[]).slice().sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));
 const optionsBrands=brands.filter(x=>x.active).map(x=>`<option value="${esc(x.name)}">${esc(x.name)}</option>`).join('');
 return `<div class="page-heading"><div><span class="eyebrow">Cadastros mestres e equipe</span><h2>Administração do L2 ONE</h2><p>Cadastre indústrias, tabelas PA/AP, produtos e acessos por setor.</p></div></div>
 <div class="box"><h3>Portabilidade da base</h3><p>Baixe estrutura SQL, dados JSON e anexos por cliente organizados em diretórios lógicos. A exportação inclui informações comerciais e financeiras; acesso restrito à administradora.</p><button type="button" onclick="exportPortable()">Exportar estrutura e dados (.zip)</button></div><div class="box"><h3>Indústrias</h3><p class="muted">O nome da indústria identifica seus preços e pedidos; para alterá-lo, revise primeiro os vínculos existentes.</p><div class="scroll"><table><tr><th>Indústria</th><th>Contato</th><th>Situação</th><th>Ações</th></tr>${brands.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.contact||'—')}</td><td>${x.active?'Ativa':'Inativa'}</td><td><button onclick="editIndustry('${esc(x.id)}')">Editar</button> <button class="secondary" onclick="deleteEntity('industry','${esc(x.id)}')">Excluir</button></td></tr>`).join('')}</table></div><form id="industryForm" onsubmit="saveIndustry(event)"><input type="hidden" name="id"><div class="row"><label>Nome da indústria<input name="name" required maxlength="120"></label><label>Contato comercial<input name="contact" maxlength="180"></label><label>Ativa<select name="active"><option value="true">Sim</option><option value="false">Não</option></select></label></div><label>Observações<textarea name="notes" rows="2" maxlength="1000"></textarea></label><button>Salvar indústria</button> <button type="button" class="secondary" onclick="this.form.reset();this.form.elements.name.readOnly=false;this.form.elements.id.value=''">Nova</button></form></div>
 <div class="box"><h3>Tabelas comerciais</h3><p class="muted">Cada indústria pode ter uma tabela para PA e outra para AP. A tabela precisa estar ativa para receber produtos novos.</p><div class="scroll"><table><tr><th>Indústria</th><th>UF</th><th>Título</th><th>Situação</th><th>Ações</th></tr>${(s.priceTables||[]).map(x=>`<tr><td>${esc(x.brand)}</td><td>${esc(x.state)}</td><td>${esc(x.title||'—')}</td><td>${x.active?'Ativa':'Inativa'}</td><td><button onclick="editPriceTable('${esc(x.id)}')">Editar</button> <button class="secondary" onclick="deleteEntity('price_table','${esc(x.id)}')">Excluir</button></td></tr>`).join('')}</table></div><form id="priceTableForm" onsubmit="savePriceTable(event)"><input type="hidden" name="id"><div class="row"><label>Indústria<select name="brand" required><option value="">Selecione</option>${optionsBrands}</select></label><label>UF<select name="state"><option>PA</option><option>AP</option></select></label><label>Nome da tabela<input name="title" required maxlength="120"></label><label>Ativa<select name="active"><option value="true">Sim</option><option value="false">Não</option></select></label></div><button>Salvar tabela</button> <button type="button" class="secondary" onclick="this.form.reset();this.form.elements.brand.disabled=false;this.form.elements.state.disabled=false;this.form.elements.id.value=''">Nova</button></form></div>
 <div class="box"><h3>Novo produto e preço</h3><p class="muted">Para lotes de produtos, use a importação em “Marcas e preços”. A chave é indústria + UF + SKU.</p><form onsubmit="saveCatalogProduct(event)"><div class="row"><label>Indústria<select name="brand" required><option value="">Selecione</option>${optionsBrands}</select></label><label>UF<select name="state"><option>PA</option><option>AP</option></select></label><label>SKU<input name="sku" required maxlength="80"></label><label>Descrição<input name="description" required maxlength="250"></label><label>Preço em reais<input name="price" inputmode="decimal" placeholder="49,90" required></label></div><button>Cadastrar produto</button> <button type="button" class="secondary" onclick="show('marcas')">Importar produtos em lote</button></form></div>
 <div class="box"><h3>Visão geral da equipe</h3><p class="muted">Atividade registrada, acessos e pendências por responsável. Uso não equivale a tempo conectado.</p><button type="button" class="secondary" onclick="loadAdminUsage()">Atualizar painel</button><div id="adminUsagePanel" aria-live="polite">Carregando atividade da equipe…</div></div><div class="box"><h3>Vendedores e acessos por setor</h3><p class="muted">Cada pessoa recebe senha provisória individual e cria sua senha no primeiro acesso. Mudanças de permissão encerram as sessões anteriores.</p><form id="memberCreateForm" onsubmit="createMember(event)"><div class="row"><label>Nome de acesso<input name="user" required minlength="2" maxlength="80"></label><label>Departamento<input name="department" maxlength="80" placeholder="Ex.: Comercial, Escritório"></label><label>Função<select name="role"><option>Vendedor</option><option>Administrativo</option><option>Gestão</option></select></label></div><fieldset><legend>Setores liberados</legend>${sectorCheckboxes(['commercial','routes'])}</fieldset><button>Cadastrar acesso</button></form><p id="adminTeamNotice" role="status"></p><button type="button" class="secondary" onclick="loadAdminTeam()">Atualizar equipe</button><div id="adminTeamList"></div></div>`;
}

function usageDate(value){if(!value)return 'Sem registro';const date=new Date(value);return Number.isNaN(date.getTime())?'Sem registro':date.toLocaleString('pt-BR')}
async function loadAdminUsage(){
 const panel=$('adminUsagePanel');if(!panel||s.user!=='Ana Paula'||!s.token)return;
 try{
  const r=await fetch(s.server+'/api/admin/usage',{headers:{Authorization:'Bearer '+s.token}});
  const data=await r.json();if(!r.ok)throw Error(data.detail||'Painel indisponível');
  const rows=data.users||[],totals={active:rows.filter(x=>x.active).length,actions:rows.reduce((n,x)=>n+x.actions7d,0),tasks:rows.reduce((n,x)=>n+x.overdueTasks,0),operations:rows.reduce((n,x)=>n+x.overdueOperations,0)};
  panel.innerHTML=`<div class="cards"><div class="card">Acessos ativos<strong>${totals.active}</strong></div><div class="card">Ações em 7 dias<strong>${totals.actions}</strong></div><div class="card">Tarefas vencidas<strong>${totals.tasks}</strong></div><div class="card">Etapas vencidas<strong>${totals.operations}</strong></div></div>
  <div class="scroll"><table><tr><th>Integrante</th><th>Último acesso</th><th>Última ação</th><th>Ações 7/30 dias</th><th>Visitas / pedidos 30 dias</th><th>Oportunidades / interações</th><th>Tarefas abertas / vencidas</th><th>Operações abertas / vencidas</th><th>Acesso</th></tr>
  ${rows.map(x=>`<tr><td><b>${esc(x.user)}</b><br>${esc(x.role||'—')}</td><td>${esc(usageDate(x.lastLogin))}</td><td>${esc(usageDate(x.lastAction))}</td><td>${x.actions7d} / ${x.actions30d}</td><td>${x.visits30d} / ${x.orders30d}</td><td>${x.opportunities30d} / ${x.interactions30d}</td><td>${x.openTasks} / ${x.overdueTasks}</td><td>${x.openOperations} / ${x.overdueOperations}</td><td>${x.active?(x.firstAccessPending?'Primeiro acesso pendente':x.activeSessions+' sessão(ões) ativa(s)'):'Inativo'}</td></tr>`).join('')}</table></div>
  <p class="muted">${esc(data.note||'')}</p><h4>Últimas ações registradas</h4>${(data.recent||[]).slice(0,20).map(x=>`<p>${esc(usageDate(x.at))} · <b>${esc(x.user)}</b> · ${esc(x.kind)} · ${esc(x.action)}</p>`).join('')||'<p>Sem registros recentes.</p>'}`;
 }catch(err){panel.textContent='Não foi possível consultar o uso da equipe: '+err.message}
}

function editIndustry(id){const x=s.industries.find(v=>v.id===id),f=$('industryForm');if(!x)return;for(const k of ['id','name','contact','notes'])f.elements[k].value=x[k]||'';f.elements.active.value=String(x.active);f.elements.name.readOnly=true;f.scrollIntoView({behavior:'smooth'})}
function saveIndustry(e){e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));d.name=d.name.trim();d.id=d.id||d.name;d.active=d.active==='true';if(!d.name||d.name.includes('|'))return alert('Informe um nome válido.');if(s.industries.some(x=>x.id!==d.id&&norm(x.name)===norm(d.name)))return alert('Indústria já cadastrada.');s.industries=s.industries.filter(x=>x.id!==d.id);s.industries.push(d);queue('industry',d);show('admin')}
function editPriceTable(id){const x=s.priceTables.find(v=>v.id===id),f=$('priceTableForm');if(!x)return;for(const k of ['id','brand','state','title'])f.elements[k].value=x[k]||'';f.elements.active.value=String(x.active);f.elements.brand.disabled=true;f.elements.state.disabled=true;f.scrollIntoView({behavior:'smooth'})}
function savePriceTable(e){e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));if(f.elements.brand.disabled)d.brand=f.elements.brand.value;if(f.elements.state.disabled)d.state=f.elements.state.value;d.id=d.id||d.brand+'|'+d.state;d.active=d.active==='true';if(!s.industries.some(x=>x.name===d.brand&&x.active))return alert('Cadastre uma indústria ativa.');s.priceTables=s.priceTables.filter(x=>x.id!==d.id);s.priceTables.push(d);queue('price_table',d);show('admin')}
function saveCatalogProduct(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),cents=parseBRLCents(d.price);d.sku=d.sku.trim();d.description=d.description.trim();if(!s.priceTables.some(x=>x.id===d.brand+'|'+d.state&&x.active))return alert('Cadastre primeiro a tabela PA/AP desta indústria.');if(!Number.isSafeInteger(cents)||cents<=0)return alert('Preço inválido.');d.id=d.brand+'|'+d.state+'|'+d.sku;d.price=(cents/100).toFixed(2);if(s.prices.some(x=>x.id===d.id||x.brand===d.brand&&x.state===d.state&&x.sku===d.sku))return alert('SKU já cadastrado nessa tabela. Edite o preço em Marcas e preços.');s.prices.push(d);queue('price',d);show('admin')}
function teamPayload(form){return {role:form.elements.role.value,department:form.elements.department.value.trim(),sectors:[...form.querySelectorAll('input[name="sectors"]:checked')].map(x=>x.value)}}
async function createMember(e){e.preventDefault();const f=e.target,d={user:f.elements.user.value.trim(),...teamPayload(f)},out=$('adminTeamNotice');try{const r=await fetch(s.server+'/api/admin/team-access',{method:'POST',headers:{Authorization:'Bearer '+s.token,'Content-Type':'application/json'},body:JSON.stringify(d)});const data=await r.json();if(!r.ok)throw Error(data.detail||'Cadastro recusado');out.textContent='Acesso criado para '+data.user+'. Senha provisória (exibida uma vez): '+data.temporaryPassword;await loadAdminTeam(true)}catch(err){out.textContent=err.message}}
async function loadAdminTeam(preserveNotice=false){const box=$('adminTeamList');if(!box)return;box.textContent='Carregando equipe…';try{const r=await fetch(s.server+'/api/admin/team-access',{headers:{Authorization:'Bearer '+s.token}});const data=await r.json();if(!r.ok)throw Error(data.detail||'Consulta recusada');s.team=data.filter(x=>x.active).map(x=>x.user);save();box.innerHTML=data.map(x=>`<form class="box" onsubmit="updateAdminTeam(event)" data-member="${esc(x.user)}"><h4>${esc(x.user)} ${x.mustChangePassword?'· primeiro acesso pendente':''}</h4><div class="row"><label>Departamento<input name="department" maxlength="80" value="${esc(x.department||'')}"></label><label>Função<select name="role">${['Vendedor','Administrativo','Gestão'].map(role=>`<option ${role===x.role?'selected':''}>${role}</option>`).join('')}</select></label><label>Situação<select name="active"><option value="true" ${x.active?'selected':''}>Ativo</option><option value="false" ${!x.active?'selected':''}>Inativo</option></select></label></div><fieldset><legend>Setores</legend>${sectorCheckboxes(x.sectors)}</fieldset>${x.user==='Ana Paula'?'Conta administradora protegida':`<button>Salvar permissões</button> <button type="button" class="secondary" onclick="resetMemberPassword('${esc(x.user)}')">Gerar senha provisória</button>`}</form>`).join('');if(!preserveNotice)$('adminTeamNotice').textContent=''}catch(err){box.textContent=err.message}}
async function updateAdminTeam(e){e.preventDefault();const form=e.target,member=form.dataset.member;if(member==='Ana Paula')return;const data={...teamPayload(form),active:form.elements.active.value==='true'},notice=$('adminTeamNotice');try{const r=await fetch(s.server+'/api/admin/team-access/'+encodeURIComponent(member),{method:'PUT',headers:{Authorization:'Bearer '+s.token,'Content-Type':'application/json'},body:JSON.stringify(data)});const out=await r.json();if(!r.ok)throw Error(out.detail||'Alteração recusada');notice.textContent='Permissões de '+member+' atualizadas. O acesso anterior foi encerrado.';await loadAdminTeam(true)}catch(err){notice.textContent=err.message}}
async function resetMemberPassword(member){if(!confirm('Gerar nova senha provisória para '+member+'? A senha anterior e sessões serão invalidadas.'))return;const notice=$('adminTeamNotice');try{const r=await fetch(s.server+'/api/admin/team-access/reset',{method:'POST',headers:{Authorization:'Bearer '+s.token,'Content-Type':'application/json'},body:JSON.stringify({user:member})});const out=await r.json();if(!r.ok)throw Error(out.detail||'Redefinição recusada');notice.textContent='Senha provisória de '+member+' (exibida uma vez): '+out.temporaryPassword;await loadAdminTeam(true)}catch(err){notice.textContent=err.message}}

function renderOffice(){
 const section=window.officeSection||'painel',buttons=[['painel','Painel'],['acoes','Plano de ação'],['rituais','Rituais'],['equipe','Equipe']];
 const sub=`<div class="subtabs">${buttons.map(([key,label])=>`<button class="${section===key?'active':''}" onclick="window.officeSection='${key}';show('office')">${label}</button>`).join('')}</div>`;
 const lists={processos:['officeProcesses','Processo','Responsável'],acoes:['officeActions','Demanda ou problema','Responsável'],comercial:['officeCommercial','Demanda','Responsável'],administrativo:['officeAdministrative','Demanda','Responsável'],rituais:['officeRituals','Momento','Responsáveis'],equipe:['officeRoles','Pessoa','Papel']};
 const actions=s.officeActions||[],open=actions.filter(x=>!['Concluída','Concluído','Cancelada','Cancelado'].includes(x.Status)),late=open.filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x.Prazo||'')&&x.Prazo<today()),due=open.filter(x=>x.Prazo===today());
 const owner=window.officeOwner||'',filtered=open.filter(x=>!owner||x['Responsável']===owner).sort((a,b)=>(a.Prazo||'9999').localeCompare(b.Prazo||'9999'));
 const selectOwner=`<label>Responsável<select onchange="window.officeOwner=this.value;show('office')"><option value="">Toda a equipe</option>${[...new Set([...teamNames(),...actions.map(x=>x['Responsável'])].filter(Boolean))].map(v=>`<option value="${esc(v)}" ${v===owner?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
 const actionRows=filtered.map(x=>`<tr><td><b>${esc(x['Demanda ou problema']||'Ação sem descrição')}</b><br><small>${esc(x['Área']||'Geral')} · ${esc(x['Próxima ação']||'Sem próxima ação')}</small></td><td>${esc(x['Responsável']||'Sem responsável')}</td><td>${esc(x.Prazo||'Sem prazo')}</td><td>${esc(x.Status||'Aberta')}</td><td><button onclick="editRecord('officeActions',${actions.indexOf(x)})">Editar</button></td></tr>`).join('');
 const queueTable=`<div class="row">${selectOwner}</div><div class="scroll"><table><tr><th>Demanda e próxima ação</th><th>Responsável</th><th>Prazo</th><th>Status</th><th>Ação</th></tr>${actionRows||'<tr><td colspan="5">Nenhuma ação aberta para este filtro.</td></tr>'}</table></div>`;
 if(section==='painel')return `<div class="page-heading"><div><span class="eyebrow">Gestão integrada</span><h2>Escritório</h2><p>Acompanhe responsáveis, prazos e entregas em um só lugar.</p></div></div>${sub}<div class="cards"><div class="card">Ações abertas<strong>${open.length}</strong></div><div class="card">Vencidas<strong>${late.length}</strong></div><div class="card">Vencem hoje<strong>${due.length}</strong></div><div class="card">Concluídas<strong>${actions.length-open.length}</strong></div></div><div class="box"><h3>Fila de trabalho</h3>${queueTable}</div><div class="box"><h3>Áreas em operação</h3><div class="cards">${[['Plano de ação',s.officeActions],['Rituais',s.officeRituals],['Equipe',s.officeRoles]].map(([name,rows])=>`<div class="card">${name}<strong>${(rows||[]).length}</strong></div>`).join('')}</div></div>`;
 const [collection,title,responsible]=lists[section]||[];if(!collection)return sub;
 const rows=s[collection]||[],ritualFilter=window.ritualOwner||'',filteredRows=rows.map((x,i)=>[x,i]).filter(([x])=>section!=='rituais'||!ritualFilter||x['Responsáveis']===ritualFilter);
 const table=section==='acoes'?queueTable:`<div class="scroll"><table><tr><th>${esc(title)}</th><th>${esc(responsible)}</th><th>Prazo / Frequência</th><th>Status</th><th>Ação</th></tr>${filteredRows.map(([x,i])=>`<tr><td><b>${esc(x[title]||x['Descrição']||'Sem descrição')}</b><br><small>${esc(x['Objetivo/Entrega']||x['Responsabilidades']||x['Saída obrigatória']||x['Observações']||'')}</small></td><td>${esc(x[responsible]||'—')}</td><td>${esc(x.Prazo||x['Prazo/SLA']||x['Frequência']||'—')}</td><td>${esc(x.Status||x['Status do processo']||'—')}</td><td><button onclick="editRecord('${collection}',${i})">Editar</button></td></tr>`).join('')||'<tr><td colspan="5">Nenhum registro nesta área.</td></tr>'}</table></div>`;
 const ritualPicker=section==='rituais'?`<label>Filtrar responsável<select onchange="window.ritualOwner=this.value;show('office')"><option value="">Todos</option>${teamOptions(ritualFilter)}</select></label>`:'';
 return `<h2>${{processos:'Processos do escritório',acoes:'Plano de ação',comercial:'Gestão comercial',administrativo:'Controle administrativo',rituais:'Rituais de gestão',equipe:'Equipe e atribuições'}[section]}</h2>${sub}<div class="box"><p class="muted">Registre entregas, atribua responsáveis e acompanhe cada atualização.</p>${ritualPicker}${table}</div>`;
}
