 if(section==='fechamento'){const current=rows.filter(x=>(x['Competência']||x.Data?.slice(0,7))===month),group=(name,type)=>value(current.filter(x=>x['Grupo DRE']===name&&x.Tipo===type)),revenue=group('Receita operacional','Receita'),deductions=group('Deduções','Despesa'),direct=group('Custo direto','Despesa'),operational=group('Despesa operacional','Despesa'),tax=group('Tributos sobre o resultado','Despesa'),unclassified=current.filter(x=>!x['Grupo DRE']||x['Grupo DRE']==='Não classificado'),finIncome=value(current.filter(x=>x['Grupo DRE']==='Resultado financeiro'&&x.Tipo==='Receita')),finExpense=value(current.filter(x=>x['Grupo DRE']==='Resultado financeiro'&&x.Tipo==='Despesa')),result=revenue-deductions-direct-operational+finIncome-finExpense-tax;const lines=[['Receita operacional',revenue],['(-) Deduções',-deductions],['(-) Custos diretos',-direct],['Margem de contribuição',revenue-deductions-direct],['(-) Despesas operacionais',-operational],['Resultado financeiro líquido',finIncome-finExpense],['(-) Tributos sobre resultado',-tax],['Resultado gerencial estimado',result]];return `<div class="box"><h3>DRE gerencial · ${esc(month)}</h3><p class="muted">Apuração pela competência dos lançamentos da empresa. Pedidos dos clientes são volume comercial da indústria, não receita automática da L2. Confirme a classificação fiscal com a contabilidade.</p><div class="scroll"><table><tr><th>Grupo</th><th>Valor</th></tr>${lines.map(([name,n])=>`<tr><td>${esc(name)}</td><td>${money(n)}</td></tr>`).join('')}</table></div><p>${unclassified.length} lançamentos sem classificação DRE. Revise-os antes do fechamento.</p></div>`}
