function financePulse(){const month=window.finMonth||today().slice(0,7),rows=s.officeFinance.filter(x=>String(x.Data||x['Competência']||'').startsWith(month)),earn=rows.filter(x=>x.Tipo==='Receita'),spent=rows.filter(x=>x.Tipo==='Despesa'),sum=(items,paid)=>items.filter(x=>paid?x['Situação']==='Pago/Recebido':true).reduce((n,x)=>n+Number(x.Valor||0),0),inflow=sum(earn,true),outflow=sum(spent,true),due=rows.filter(x=>x['Situação']!=='Pago/Recebido'&&x.Vencimento&&x.Vencimento<today()),sale=s.orders.filter(x=>x.date?.startsWith(month)&&!['Cancelado','Orçamento'].includes(x.status)).reduce((n,x)=>n+Number(x.amount||0),0);const series=Array.from({length:6},(_,i)=>{const date=new Date(Number(month.slice(0,4)),Number(month.slice(5,7))-1-i,1),key=date.toLocaleDateString('sv-SE').slice(0,7),rr=s.officeFinance.filter(x=>String(x.Data||x['Competência']||'').startsWith(key));return {key,entrada:rr.filter(x=>x.Tipo==='Receita'&&x['Situação']==='Pago/Recebido').reduce((n,x)=>n+Number(x.Valor||0),0),saida:rr.filter(x=>x.Tipo==='Despesa'&&x['Situação']==='Pago/Recebido').reduce((n,x)=>n+Number(x.Valor||0),0)}}).reverse();const maximum=Math.max(1,...series.flatMap(x=>[x.entrada,x.saida]));return `<div class="box"><h3>Acompanhamento mensal</h3><label>Mês<input type="month" value="${esc(month)}" onchange="window.finMonth=this.value;show('finance')"></label><div class="cards"><div class="card">Entradas realizadas<strong>${money(inflow)}</strong></div><div class="card">Saídas realizadas<strong>${money(outflow)}</strong></div><div class="card">Resultado<strong>${money(inflow-outflow)}</strong></div><div class="card">Previsto a receber / pagar<strong>${money(sum(earn,false)-inflow)} / ${money(sum(spent,false)-outflow)}</strong></div><div class="card">Vencidos<strong>${due.length}</strong></div><div class="card">Pedidos comerciais<strong>${money(sale)}</strong></div></div><h4>Evolução: entradas e saídas realizadas</h4>${series.map(x=>`<p>${esc(x.key)} · entradas ${money(x.entrada)}<br><span style="display:inline-block;background:#9c875a;height:9px;width:${Math.round(x.entrada/maximum*90)}%"></span><br>saídas ${money(x.saida)}<br><span style="display:inline-block;background:#334e59;height:9px;width:${Math.round(x.saida/maximum*90)}%"></span></p>`).join('')}<p class="muted">Registros financeiros e caixa diário são fontes separadas; não some os dois controles sem conciliação.</p></div>`}
function saveGoal(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.amount=parseBRLCents(d.amount)/100;if(!Number.isFinite(d.amount)||d.amount<0)return alert('Informe uma meta válida em reais.');d.brand=(d.brand||'').trim();d.id=d.month+'-'+d.user.toLowerCase().replace(/[^a-z0-9]+/g,'-')+(d.brand?'-'+commissionKey(d.brand):'');let i=s.goals.findIndex(x=>x.id===d.id);if(i<0)s.goals.push(d);else s.goals[i]=d;queue('goal',d);window.reportMonth=d.month;show('gestao')}
