function commissionPanel(month){if(!financeAllowed())return '';const brands=[...new Map([...s.industries.map(x=>x.name),...s.prices.map(x=>x.brand),...s.orders.map(x=>x.brand),...s.commissionRates.map(x=>x.brand)].filter(Boolean).map(x=>[commissionKey(x),x])).values()].sort((a,b)=>a.localeCompare(b,'pt-BR'));const rows=brands.map(brand=>{const key=commissionKey(brand),rate=s.commissionRates.find(x=>x.id===key)?.rate,received=s.commissionReceipts.find(x=>x.id===month+'|'+key)?.received||0,billedCents=s.orders.filter(x=>x.date?.startsWith(month)&&x.status==='Faturado'&&commissionKey(x.brand)===key).reduce((sum,x)=>sum+Math.round(Number(x.amount||0)*100),0),expected=rate===undefined?null:Math.round(billedCents*Number(rate)/100);return `<tr><td>${esc(brand)}</td><td>${rate===undefined?'Não informado':esc(Number(rate).toLocaleString('pt-BR',{maximumFractionDigits:2}))+'%'}</td><td>${money(billedCents/100)}</td><td>${expected===null?'—':money(expected/100)}</td><td>${money(received)}</td><td>${expected===null?'—':money((expected-Math.round(Number(received)*100))/100)}</td></tr>`}).join('');return `<div class="box"><h3>Comissões por indústria</h3><p class="muted">Previsão calculada sobre pedidos marcados como Faturado no mês. Registre o valor efetivamente recebido para acompanhar o saldo. Ajustes, impostos e regras de liquidez não são calculados automaticamente.</p><div class="scroll"><table><tr><th>Indústria</th><th>Comissão</th><th>Faturado</th><th>Previsão</th><th>Recebido</th><th>Saldo previsto</th></tr>${rows}</table></div><form onsubmit="saveCommissionRate(event)"><div class="row"><label>Indústria<select name="brand" required><option value="">Selecione</option>${brands.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></label><label>Percentual de comissão (%)<input name="rate" inputmode="decimal" placeholder="5,00" required></label></div><button>Salvar percentual</button></form><form onsubmit="saveCommissionReceipt(event)"><div class="row"><label>Indústria<select name="brand" required><option value="">Selecione</option>${brands.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></label><label>Mês da comissão<input name="month" type="month" value="${esc(month)}" required></label><label>Valor recebido no mês (R$)<input name="received" inputmode="decimal" placeholder="0,00" required></label></div><button>Salvar valor recebido</button></form></div>`}
function done(id){let t=s.tasks.find(x=>x.id===id);t.status='Concluída';queue('task',t);show('hoje')}
function addRoute(id){let d=window.routeDay||today(),n=s.routes.filter(x=>x.date===d).length;if(n>=10){alert('A rota já tem 10 clientes. Retire um para adicionar outro.');return}let r={id:uid(),date:d,clientId:id,order:n+1,user:window.routeOwner||s.user};s.routes.push(r);queue('route',r);show('rota')}
